import "server-only";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import type { Block, IndexEntry, Section, Slice } from "./types";

// generated by scripts/mafatih/extract.py from the alhassanain.org PDF
const ROOT = path.join(process.cwd(), "content", "mafatih");
const ID_RE = /^[a-z0-9-]{1,80}$/;

export const getIndex = cache(async (): Promise<IndexEntry[]> => {
  return JSON.parse(await readFile(path.join(ROOT, "index.json"), "utf8"));
});

export const getSection = cache(async (id: string): Promise<Section | null> => {
  if (!ID_RE.test(id)) return null;
  try {
    return JSON.parse(await readFile(path.join(ROOT, "s", `${id}.json`), "utf8"));
  } catch {
    return null;
  }
});

const norm = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");

/** Blocks of one sub-part of a section: from heading `h` (prefix match) up to the next heading.
 *  Without `h`: everything before the first heading. */
export function sliceBlocks(blocks: Block[], h?: string): Block[] {
  if (!h) {
    const end = blocks.findIndex((b) => b.t === "h");
    return end < 0 ? blocks : blocks.slice(0, end);
  }
  const key = norm(h);
  const start = blocks.findIndex((b) => b.t === "h" && norm(b.x).startsWith(key));
  if (start < 0) return blocks;
  const rel = blocks.slice(start + 1).findIndex((b) => b.t === "h");
  return blocks.slice(start + 1, rel < 0 ? undefined : start + 1 + rel);
}

export async function getSlice(s: Slice) {
  const sec = await getSection(s.id);
  if (!sec) return null;
  return { ...sec, blocks: "h" in s ? sliceBlocks(sec.blocks, s.h) : sec.blocks };
}

export type TocNode = IndexEntry & { children: TocNode[] };

/** index → 3-level tree (section / chapter / item). Items without a chapter hang off the section. */
export const getTree = cache(async (): Promise<TocNode[]> => {
  const roots: TocNode[] = [];
  const stack: TocNode[] = [];
  for (const e of await getIndex()) {
    const node: TocNode = { ...e, children: [] };
    while (stack.length && stack[stack.length - 1].level >= e.level) stack.pop();
    if (stack.length) stack[stack.length - 1].children.push(node);
    else roots.push(node);
    stack.push(node);
  }
  return roots;
});

/** previous / next readable entry (skips empty chapter headers) */
export async function neighbours(id: string) {
  const all = (await getIndex()).filter((e) => e.words > 0);
  const i = all.findIndex((e) => e.id === id);
  return { prev: i > 0 ? all[i - 1] : null, next: i >= 0 && i < all.length - 1 ? all[i + 1] : null };
}

/** chapter / section titles above an entry */
export async function breadcrumbs(id: string) {
  const idx = await getIndex();
  const i = idx.findIndex((e) => e.id === id);
  if (i < 0) return [];
  const out: IndexEntry[] = [];
  let lvl = idx[i].level;
  for (let j = i - 1; j >= 0 && lvl > 0; j--) {
    if (idx[j].level < lvl) {
      out.unshift(idx[j]);
      lvl = idx[j].level;
    }
  }
  return out;
}
